{
  "early_commentary": {
    "label": "劉孝標注",
    "notes": [
      {
        "ref": "L01",
        "text": "(詳/未)"
      },
      {
        "ref": "L02",
        "text": "(泰事五斗米道以謀反誅恩逸逃於海上/晉安帝紀曰孫恩一名靈秀琅邪人叔父)"
      },
      {
        "ref": "L03",
        "text": "(臨海太守辛昺斬首送之/聚衆十萬人攻沒郡縣後為)"
      },
      {
        "ref": "L04",
        "text": "(别見/山松)"
      }
    ]
  },
  "frozen_questions": [
    {
      "gap": "袁府君的具體身份（如吳郡太守）及其與陳遺的官方從屬關係未被說明，使讀者難以理解陳遺作為主簿為何必須隨軍出征。",
      "question_id": "Q1",
      "story_span": "袁府君即日便征"
    },
    {
      "gap": "孫恩之亂的性質與規模未被交代，讀者無法判斷這是地方騷亂還是重大戰爭，影響對吳郡緊急狀態和後續戰敗意義的感知。",
      "question_id": "Q2",
      "story_span": "孫恩\n賊出吳郡"
    },
    {
      "gap": "未說明陳遺在潰敗中如何保存焦飯，以及這袋焦飯是否足以支持他存活，使『獨活』的幸運性與孝報關聯缺乏具體的因果支撐。",
      "question_id": "Q3",
      "story_span": "遺獨以焦飯\n\n得活"
    }
  ],
  "later_commentary": {
    "label": "余嘉錫箋疏",
    "notes": [
      {
        "layer": "jianshu_note",
        "ref": "J01",
        "source_labels": [
          "太平御覽"
        ],
        "speaker": null,
        "text": "〔一〕 御覽四百十一引宋躬孝子傳曰：「陳遺吳郡人，少為郡吏。」"
      },
      {
        "layer": "jianshu_note",
        "ref": "J02",
        "source_labels": [],
        "speaker": "余嘉錫",
        "text": "〔二〕 嘉錫案：宋躬孝子傳及南史均止云「少為郡吏」，不知其為主簿也。"
      },
      {
        "layer": "jianshu_note",
        "ref": "J03",
        "source_labels": [
          "晉書"
        ],
        "speaker": "余嘉錫",
        "text": "〔三〕 隋志有晉臨海太守辛德遠集五卷。新唐志有辛昺集四卷。文廷式補晉書藝文志六云：「德遠蓋昺字，唐人諱昺，故稱其字也。」嘉錫案：晉書孫恩傳作辛景，亦避諱改字。"
      },
      {
        "layer": "jianshu_note",
        "ref": "J04",
        "source_labels": [
          "晉書"
        ],
        "speaker": "余嘉錫",
        "text": "晉書安帝紀：「元興元年三月，臨海太守辛景擊孫恩，斬之。」又孫恩傳：「恩復寇臨海，臨海太守辛昺討破之。恩窮蹙赴海自沈。」嘉錫案：辛景即辛昺，蓋唐人修史時避諱改之。"
      },
      {
        "layer": "jianshu_note",
        "ref": "J05",
        "source_labels": [
          "太平御覽"
        ],
        "speaker": "余嘉錫",
        "text": "宋書高祖紀：「元興三年，兗州刺史辛禺懷貳。會北青州刺史劉該反，禺求征該，次淮陰，又反。禺長史羊穆之斬禺，傳首京師。」湘潭孫虨宋書攷論云：「禺、昺字形相似，蓋即一人。」嘉錫案：元興元年三月，桓玄總百揆。二年十二月，篡位。辛昺若於三年為兗州刺史，則必玄所用。御覽三百三十七有辛昺洛戍時與桓郎牋曰：「桓振武令下官將千二百人襲□營。」振武者，桓石民也。則昺乃桓氏舊部，宜其降後復叛矣。"
      },
      {
        "layer": "jianshu_note",
        "ref": "J06",
        "source_labels": [],
        "speaker": "程炎震",
        "text": "〔四〕 程炎震云：「隆安五年，袁山松死於滬瀆。」"
      },
      {
        "layer": "jianshu_note",
        "ref": "J07",
        "source_labels": [
          "太平御覽"
        ],
        "speaker": "余嘉錫",
        "text": "〔五〕 宋躬孝子傳又曰：「母晝夜涕泣，目為失明。耳無所聞。遺還入戶，再拜號咽，母豁然有聞見。」嘉錫案：陳遺見南史孝義傳，較此為詳。考法苑珠林四十九、御覽四百十一引宋躬孝子傳，廣記百六十二引孝子傳，並有陳遺事。字句大同小異。蓋同引一書也。南史云：「母晝夜泣涕，目為失明，耳無所聞。遺還入戶，再拜號咽，母豁然即明。」此事世說所無，而宋躬傳有之。蓋即南史所本。且不獨此一事而已。凡孝義傳中所載，如賈恩、丘傑、孫棘、何子平、王虛之、華寶、韓靈敏諸人，無不采自宋躬書者。考之類聚、御覽所引，便可見矣。宋躬孝子傳二十卷，隋書經籍志著錄，不詳時代。兩唐志作宗躬。姚振宗隋志考證二十、據南齊書孔稚圭傳，永明中有廷尉監宋躬。南史袁彖傳有江陵令宗躬。隋志別集類有齊平西諮議宗躬集。因以考得其仕履。今案：南史王虛之傳中有齊永明閒事，則宋躬書…"
      }
    ]
  },
  "primary_text": {
    "label": "世說新語正文",
    "text": "呉郡陳遺家至孝母好食鐺底焦飯遺作郡主簿\n恒裝一囊每煮食輙貯録焦飯歸以遺母後值孫恩\n賊出吳郡\n袁府君即日便征\n遺己聚歛得數斗焦飯未展歸家遂帶以從軍戰於\n滬瀆敗軍人潰散逃走山澤皆多饑死遺獨以焦飯\n\n得活時人以為純孝之報也"
  },
  "story_id": "01-dexing-045"
}
